12	#define METADEF_CXX_FUNC_COUNTER_H
13	#include <iostream>
14	#include <vector>
15	namespace ge {
16	struct FuncCounter {
17	  static size_t construct_times;
18	  static size_t copy_construct_times;
19	  static size_t move_construct_times;
20	  static size_t copy_assign_times;
21	  static size_t move_assign_times;
22	  static size_t destruct_times;
23	  FuncCounter() {
24	    ++construct_times;
25	  }
26	  ~FuncCounter() {
27	    ++destruct_times;
28	  }
29	  FuncCounter(const FuncCounter &) {
30	    ++copy_construct_times;
31	  }
32	  FuncCounter(FuncCounter &&) noexcept {
33	    ++move_construct_times;
34	  }
35	  FuncCounter &operator=(const FuncCounter &) {
36	    ++copy_assign_times;
37	    return *this;
